package main

import (
	"embed"
	"io/fs"
	"log/slog"
	"os"
	"path"
	"path/filepath"
	"strings"

	"github.com/goccy/go-yaml"

	"github.com/dbis-ilm/personalrag/internal/i18n"
	"github.com/dbis-ilm/personalrag/internal/paths"
	"github.com/dbis-ilm/personalrag/internal/store"
)

// The demo collections (demo/, generated by cmd/demogen) ship inside the
// app. "Add demo collections" unpacks them into <data>/demo and indexes
// them; their example questions come from demo/cases.yaml.

//go:embed demo
var demoFS embed.FS

// demoPrefix marks the IDs of demo collections; removing one also removes
// its unpacked files.
const demoPrefix = "demo-"

// demoSets are the demo folders in the order they are added; the name is
// an i18n key.
var demoSets = []struct {
	folder, name string
	color        int // index into collectionColors
}{
	{"protokolle", "demo.protokolle", 0},
	{"angebote", "demo.angebote", 2},
	{"skript", "demo.skript", 3},
	{"pruefung", "demo.pruefung", 1},
}

// DemoQuestion is an example question of a demo collection.
type DemoQuestion struct {
	Question     string `json:"question"`
	Mode         string `json:"mode"` // search | answer | agent
	CollectionID string `json:"collectionId"`
}

func (s *AppService) demoDir() string { return filepath.Join(s.dataDir, "demo") }

// AddDemo unpacks and indexes the demo collections that are not there yet
// and returns how many it added.
func (s *AppService) AddDemo() (int, error) {
	c, err := s.current()
	if err != nil {
		return 0, err
	}
	colls, err := c.st.Collections(s.appCtx)
	if err != nil {
		return 0, err
	}
	have := map[string]bool{}
	for _, cl := range colls {
		have[cl.ID] = true
	}
	added := 0
	for _, set := range demoSets {
		id := demoPrefix + set.folder
		if have[id] {
			continue
		}
		dir := filepath.Join(s.demoDir(), set.folder)
		if err := unpackDemo(set.folder, dir); err != nil {
			return added, err
		}
		cl := store.Collection{ID: id, Name: i18n.T(set.name), Color: collectionColors[set.color], Folders: []string{paths.Canonical(dir)}}
		if err := c.st.CreateCollection(s.appCtx, cl); err != nil {
			return added, err
		}
		added++
		if c.ix != nil {
			go func() {
				if err := c.ix.ScanCollection(s.appCtx, cl); err != nil {
					slog.Warn("demo scan failed", "collection", cl.ID, "err", err)
				}
			}()
		}
	}
	if added > 0 {
		s.sourcesChanged()
	}
	return added, nil
}

// unpackDemo writes the embedded folder to dir, replacing what is there.
func unpackDemo(folder, dir string) error {
	if err := os.RemoveAll(dir); err != nil {
		return err
	}
	root := path.Join("demo", folder)
	return fs.WalkDir(demoFS, root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		target := filepath.Join(dir, filepath.FromSlash(strings.TrimPrefix(p, root)))
		if d.IsDir() {
			return os.MkdirAll(target, 0o755)
		}
		data, err := demoFS.ReadFile(p)
		if err != nil {
			return err
		}
		return os.WriteFile(target, data, 0o644)
	})
}

// removeDemoFiles deletes the unpacked files of a demo collection; only
// below <data>/demo, never a user's folder.
func (s *AppService) removeDemoFiles(id string) {
	folder := strings.TrimPrefix(id, demoPrefix)
	if folder == id || folder == "" || strings.ContainsAny(folder, `/\.`) {
		return
	}
	dir := filepath.Join(s.demoDir(), folder)
	if !paths.Within(dir, s.demoDir()) {
		return
	}
	if err := os.RemoveAll(dir); err != nil {
		slog.Warn("removing demo files failed", "dir", dir, "err", err)
	}
}

// DemoQuestions returns example questions for a demo collection, or for
// every demo collection that exists when collectionID is "" (all
// collections). Other collections have none.
func (s *AppService) DemoQuestions(collectionID string) ([]DemoQuestion, error) {
	c, err := s.current()
	if err != nil {
		return nil, err
	}
	colls, err := c.st.Collections(s.appCtx)
	if err != nil {
		return nil, err
	}
	have := map[string]bool{}
	for _, cl := range colls {
		have[cl.ID] = true
	}
	cases, err := demoCases()
	if err != nil {
		return nil, err
	}
	out := []DemoQuestion{}
	for _, dc := range cases {
		id := demoPrefix + dc.Folder
		if !have[id] || (collectionID != "" && collectionID != id) {
			continue
		}
		out = append(out, DemoQuestion{Question: dc.Question, Mode: dc.Mode, CollectionID: id})
	}
	return out, nil
}

type demoCase struct {
	Folder   string `yaml:"folder"`
	Mode     string `yaml:"mode"`
	Question string `yaml:"question"`
}

func demoCases() ([]demoCase, error) {
	data, err := demoFS.ReadFile("demo/cases.yaml")
	if err != nil {
		return nil, err
	}
	var f struct {
		Cases []demoCase `yaml:"cases"`
	}
	if err := yaml.Unmarshal(data, &f); err != nil {
		return nil, err
	}
	return f.Cases, nil
}
